void _touchAnalyticsClientEvent(AnalyticsClientEvent v) {
  if (v is AnalyticsClientEventPageView) _touchAnalyticsClientEventPageView(v);
  if (v is AnalyticsClientEventPageEngagement) _touchAnalyticsClientEventPageEngagement(v);
  if (v is AnalyticsClientEventProductView) _touchAnalyticsClientEventProductView(v);
  if (v is AnalyticsClientEventProductListView) _touchAnalyticsClientEventProductListView(v);
  if (v is AnalyticsClientEventSearch) _touchAnalyticsClientEventSearch(v);
}

void _touchAnalyticsClientEventPageView(AnalyticsClientEventPageView v) {
  v.toJson();
  v.occurredAt;
  v.url;
  v.pageViewId;
  v.name;
  if (v.referrer != null) { v.referrer; }
}

void _touchAnalyticsClientEventPageEngagement(AnalyticsClientEventPageEngagement v) {
  v.toJson();
  v.occurredAt;
  v.url;
  v.pageViewId;
  v.name;
  v.visibleMs;
}

void _touchAnalyticsClientEventProductView(AnalyticsClientEventProductView v) {
  v.toJson();
  v.occurredAt;
