}

void _touchAnalyticsBatch(AnalyticsBatch v) {
  v.toJson();
  v.storeCode;
  v.visitorId;
  v.sessionId;
  for (final x in v.events) _touchAnalyticsClientEvent(x);
  if (v.context != null) { _touchAnalyticsBatchContext(v.context!); }
}

void _touchAnalyticsBatchContext(AnalyticsBatchContext v) {
  v.toJson();
  if (v.webdriver != null) { v.webdriver; }
}

